45	func TestExists(t *testing.T) {
46		cases := []struct {
47			name       string
48			status     int
49			wantExists bool
50			wantErr    bool
51		}{
52			{"204", http.StatusNoContent, true, false},
53			{"200", http.StatusOK, true, false},
54			{"404", http.StatusNotFound, false, false},
55			{"500", http.StatusInternalServerError, false, true},
56		}
57		for _, c := range cases {
58			t.Run(c.name, func(t *testing.T) {
59				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
60					if r.Method != http.MethodHead {
61						t.Errorf("expected HEAD, got %s", r.Method)
62					}
63					if r.URL.Path != "/v1/modules/iac/comply/aws/1.0.0/download" {
64						t.Errorf("unexpected path: %s", r.URL.Path)
65					}
66					w.WriteHeader(c.status)
67				}))
68				defer srv.Close()
69	
70				cli := New(srv.URL, WithHTTPClient(srv.Client()))
71				exists, err := cli.Exists(context.Background(), testModule())
72				if (err != nil) != c.wantErr {
73					t.Errorf("err = %v, wantErr %v", err, c.wantErr)
74				}
75				if exists != c.wantExists {
76					t.Errorf("exists = %v, want %v", exists, c.wantExists)
77				}
78			})
79		}
